import{z as o,x as i,o as r,c as p,q as B,j as t,D as l,d as a,s as n,S as s,b as e}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"超参搜索工程","description":"","frontmatter":{"title":"超参搜索工程","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/ti-hparam-search-eng.md","filePath":"llm/ti-hparam-search-eng.md","lastUpdated":1791413859000}'),h={name:"llm/ti-hparam-search-eng.md"};function m(d,E,C,D,c,g){const A=i("Mermaid");return r(),p("div",null,[E[2]||(E[2]=B('<h1 id="超参搜索工程" tabindex="-1">超参搜索工程 <a class="header-anchor" href="#超参搜索工程" aria-label="Permalink to &quot;超参搜索工程&quot;">​</a></h1><div class="epigraph"><p>超参搜索的产出不是一组「最优值」，而是一张可迁移的响应面；搜索工程的任务是用最小预算把这张面画对。</p><footer>—— 据 Kaplan 扩展律、Chinchilla 与小规模代理实验的迁移实践整理</footer></div><p><a href="/llm/ti-numerical-health">上一课</a>把数值异常交给绊网，训练敢无人值守地跑。敢跑之后的问题是跑什么：学习率、批次、正则从哪来。机理各课已有：学习率与批次的耦合在<a href="/llm/lr-batch-scaling-law">学习率与批次缩放律</a>，临界批次的判定在<a href="/llm/gradient-noise-scale">梯度噪声尺度</a>，小模型外推的可行性在<a href="/llm/proxy-model-experiments">小模型代理实验</a>，计算预算怎么分给规模与数据在 <a href="/llm/chinchilla">Chinchilla</a>。本课把这些机理装成一条<strong>搜索流水线</strong>：空间怎么设计、预算怎么分、坏点怎么早杀、结果怎么归档。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>搜索失败的形态不是「没找到好点」，而是三种浪费。<strong>空间浪费</strong>：把耦合维度当独立维度——学习率与批次被缩放律绑成一个自由度，分开扫等于把一维问题烧成二维预算。<strong>规模浪费</strong>：在目标规模上直接扫，一组学习率点要烧数天机群时间；小规模扫、大规模验证的迁移路径没有制度，全凭个人勇气。<strong>方差浪费</strong>：两个配置差 0.002 的验证损失就被判胜负，而种子间方差本身就有 0.005——没有噪声下界的比较是在比随机数。</p><p><span class="marginnote">数字实例：若种子间验证损失的标准差是 0.005，那么 0.002 的差距完全落在噪声里，谁赢都可能是运气。按两倍标准差作安全线，两个配置至少要差约 0.01 才谈得上可信——所以先花小预算测方差，再决定比较用的分辨率。</span></p><h3 id="空间与预算的结构" tabindex="-1">空间与预算的结构 <a class="header-anchor" href="#空间与预算的结构" aria-label="Permalink to &quot;空间与预算的结构&quot;">​</a></h3><p>空间设计的第一原则是<strong>按量纲结构化</strong>：学习率对数均匀取点（每数量级 3 到 5 个），批次由<a href="/llm/gradient-noise-scale">梯度噪声尺度</a>定临界区后只在区内取值，warmup 与衰减写成峰值学习率的比例而不是绝对值——比例化的参数随规模更稳，µP 一类参数化正是这个思路的系统化。预算设计给两条硬约束：搜索总预算不超过项目预算的一成；每个点的种子数由<a href="/llm/eval-variance-seed">评测方差与种子</a>的口径反推，先测方差再定重复数。</p><p><span class="marginnote">早期淘汰的依据是排序稳定性：学习率等强效应超参在训练前 5% 到 10% 的相对排序，通常已与终值一致；但弱效应超参（正则、dropout）的早期排序不可信——早杀只对强效应维度执行，且淘汰线要按外推斜率定，不按绝对值定。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>流水线按四步走。<strong>扫</strong>：代理规模上随机搜索强效应维度，弱效应维度沿用上一张响应面的值——搜索是增量更新认知，不是每项目从零重扫。<strong>筛</strong>：用前段损失斜率外推终值排序，淘汰明确落后的点；外推前按<a href="/llm/loss-curve-phases">损失曲线的阶段</a>剔掉 warmup 与尖峰段——该课说过，阶段边界是拟合之前的标注工作。<strong>验</strong>：幸存的前几个点在目标规模各验一个短程，配 2 到 3 个种子，差异超过噪声下界才下结论。<strong>存</strong>：响应面（配置到指标的完整映射，含失败点）落进实验跟踪系统，成为下一项目的先验。</p>',11)),(r(),t(s,null,{default:l(()=>[n(A,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%5B%22%E7%BB%93%E6%9E%84%E5%8C%96%E7%A9%BA%E9%97%B4%3A%20lr%20%E5%AF%B9%E6%95%B0%20%2B%20%E6%89%B9%E6%AC%A1%E6%8C%89%E4%B8%B4%E7%95%8C%E5%8C%BA%20%2B%20%E6%AF%94%E4%BE%8B%E5%8C%96%E6%97%A5%E7%A8%8B%22%5D%20--%3E%20SW%5B%22%E4%BB%A3%E7%90%86%E8%A7%84%E6%A8%A1%E9%9A%8F%E6%9C%BA%E6%90%9C%E7%B4%A2%22%5D%0A%20%20SW%20--%3E%20KILL%7B%22%E5%89%8D%E6%AE%B5%E5%A4%96%E6%8E%A8%E6%8E%92%E5%BA%8F%22%7D%0A%20%20KILL%20--%3E%7C%E6%98%8E%E6%98%BE%E8%90%BD%E5%90%8E%7C%20DROP%5B%22%E6%97%A9%E6%9D%80%2C%20%E8%AE%B0%E5%BD%95%E5%A4%96%E6%8E%A8%E8%AF%81%E6%8D%AE%22%5D%0A%20%20KILL%20--%3E%7C%E5%B9%B8%E5%AD%98%7C%20VER%5B%22%E7%9B%AE%E6%A0%87%E8%A7%84%E6%A8%A1%E7%9F%AD%E7%A8%8B%E9%AA%8C%E8%AF%81%2C%20%E5%A4%9A%E7%A7%8D%E5%AD%90%22%5D%0A%20%20VER%20--%3E%20NS%7B%22%E5%B7%AE%E5%80%BC%E8%B6%85%E8%BF%87%E5%99%AA%E5%A3%B0%E4%B8%8B%E7%95%8C%3F%22%7D%0A%20%20NS%20--%3E%7C%E6%98%AF%7C%20WIN%5B%22%E5%AE%9A%E8%B6%85%E5%8F%82%2C%20%E5%93%8D%E5%BA%94%E9%9D%A2%E5%85%A5%E6%A1%A3%22%5D%0A%20%20NS%20--%3E%7C%E5%90%A6%7C%20MORE%5B%22%E5%8A%A0%E7%A7%8D%E5%AD%90%E6%88%96%E5%88%A4%E5%B9%B3%E5%B1%80%22%5D%0A"})]),fallback:l(()=>[...E[0]||(E[0]=[a(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=e("h2",{id:"机制",tabindex:"-1"},[a("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=e("p",null,[a("结构化空间有效的机理是"),e("strong",null,"自由度压缩"),a("：真正的搜索维数远小于表面超参个数，耦合维度绑成一个、绝对值换成比例，预算从网格爆炸里解放出来。早杀有效的机理是强效应超参影响的是损失曲线的"),e("strong",null,"斜率"),a("而非终点装饰，斜率在前期已可分辨；反过来，弱效应超参影响终点的方式常被前期噪声淹没，所以只对强效应维度早杀。响应面入档的机理是复利：本次搜索回答「这批配置怎么样」，下次回答「往哪个方向更优」；没有历史响应面，每个项目都重付第一次的学费。")],-1)),(r(),t(s,null,{default:l(()=>[n(A,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20LR%0A%20%20S%5B%22%E8%A1%A8%E9%9D%A2%E8%B6%85%E5%8F%82%3A%20lr%2C%20%E6%89%B9%E6%AC%A1%2C%20warmup%2C%20%E8%A1%B0%E5%87%8F%2C%20%E6%AD%A3%E5%88%99%22%5D%20--%3E%20C%7B%22%E5%93%AA%E4%BA%9B%E5%8F%AF%E4%BB%A5%E7%BB%91%E4%BD%8F%E4%B8%8D%E6%89%AB%3F%22%7D%0A%20%20C%20--%3E%7C%22lr%20%E4%B8%8E%E6%89%B9%E6%AC%A1%3A%20%E7%BC%A9%E6%94%BE%E5%BE%8B%E8%80%A6%E5%90%88%22%7C%20M%5B%22%E7%BB%91%E6%88%90%E4%B8%80%E4%B8%AA%E8%87%AA%E7%94%B1%E5%BA%A6%2C%20%E5%8F%AA%E6%89%AB%20lr%22%5D%0A%20%20C%20--%3E%7C%22warmup%20%E4%B8%8E%E8%A1%B0%E5%87%8F%3A%20%E9%9A%8F%E5%B3%B0%E5%80%BC%E7%BC%A9%E6%94%BE%22%7C%20R%5B%22%E5%86%99%E6%88%90%E5%B3%B0%E5%80%BC%20lr%20%E7%9A%84%E6%AF%94%E4%BE%8B%22%5D%0A%20%20C%20--%3E%7C%22%E6%AD%A3%E5%88%99%E7%B1%BB%3A%20%E5%BC%B1%E6%95%88%E5%BA%94%22%7C%20K%5B%22%E6%B2%BF%E7%94%A8%E4%B8%8A%E6%AC%A1%E5%93%8D%E5%BA%94%E9%9D%A2%E7%9A%84%E5%80%BC%22%5D%0A%20%20M%20--%3E%20D%5B%22%E6%9C%89%E6%95%88%E7%BB%B4%E6%95%B0%E9%99%8D%E5%88%B0%201%20%E5%88%B0%202%22%5D%0A%20%20R%20--%3E%20D%0A%20%20K%20--%3E%20D%0A%20%20D%20--%3E%20B%5B%22%E4%BA%8C%E7%BB%B4%E7%BD%91%E6%A0%BC%E9%A2%84%E7%AE%97%E5%8F%98%E4%B8%80%E7%BB%B4%E6%89%AB%E6%8F%8F%22%5D%0A"})]),fallback:l(()=>[...E[1]||(E[1]=[a(" Loading... ",-1)])]),_:1})),E[5]||(E[5]=B('<p><span class="marginnote">术语翻译：响应面就是「配置到结果的函数地形」——把每个超参组合看成地图上一个点，高度是验证损失，整张地图就是响应面。搜索的目标不是捡一颗孤立的珍珠（单点最优值），而是画出等高线：下次换了规模，还能顺着地势找到谷底。</span></p><p>搜索与代理实验的衔接有一条机制约束：迁移假设「最优区随规模平滑移动」，数据规模或配比剧变时失效，验证一步不可省——<a href="/llm/proxy-model-experiments">小模型代理实验</a>给的是效率，不是免检。</p><p><span class="marginnote">常见误区：初学者容易把代理规模扫出的最优超参直接抄给目标规模，实际上这依赖「最优区随规模平滑移动」的假设——数据配比剧变或规模跨度太大时并不成立。代理实验给的是方向和候选名单，目标规模上的短程验证永远不能省。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课管搜索的工程，不管超参的语义：耦合为何成立，机理课已写；搜索也不替代缩放律拟合——规模与数据的预算分配用 <a href="/llm/chinchilla">Chinchilla</a> 的口径，搜索只在给定预算内调动态。贝叶斯优化适合高维离散空间；语言模型常用空间低维且连续，随机搜索加早杀通常够用，引入复杂搜索器前先确认瓶颈不是预算结构。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>空间按量纲结构化：学习率对数取点，耦合维度绑成一个自由度。</li><li>搜索预算封顶约一成，种子数由实测方差反推，先有噪声下界再比胜负。</li><li>早杀只对强效应维度执行，依据前段外推的排序稳定性。</li><li>产出归档为响应面（含失败点），成为下次搜索的先验。</li><li>出处：Kaplan et al., 2020 与 Hoffmann et al., 2022 的缩放口径；据小规模代理实验迁移实践整理。</li></ul>',7))])}const _=o(h,[["render",m]]);export{u as __pageData,_ as default};
